from collections import deque
R=C=16
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==7 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); pts=[]
  for x,y in q:
   pts.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    nx,ny=x+dx,y+dy
    if 0<=nx<R and 0<=ny<C and grid[nx][ny]!=7 and (nx,ny) not in seen:
     seen.add((nx,ny));q.append((nx,ny))
  vals={grid[x][y] for x,y in pts}
  comps.append((min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts),len(pts),vals,pts))
[(a,b,c,d,n,v) for a,b,c,d,n,v,p in comps]

out=[row[:] for row in grid]
for a,b,c,d,n,v,pts in comps:
 if {5,6,8}.issubset(v):
  for r,c0 in pts: out[r][c0]=7
[(a,b,c,d,n,v) for a,b,c,d,n,v,p in comps if {5,6,8}.issubset(v)], '\n'.join(' '.join(map(str,row)) for row in out)
